  public function executeUpdate()
  {
    if (!$this->getRequestParameter('docsolicitudprestamo_id'))
    {
      $doc_solicitud_prestamo = new DocSolicitudPrestamo();
    }
    else
    {
      $doc_solicitud_prestamo = DocSolicitudPrestamoPeer::retrieveByPk($this->getRequestParameter('docsolicitudprestamo_id'));
      $this->forward404Unless($doc_solicitud_prestamo);
    }
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    //$doc_solicitud_prestamo->setDocsolicitudprestamoId($this->getRequestParameter('docsolicitudprestamo_id'));
    $doc_solicitud_prestamo->setDocumentacionId($this->getRequestParameter('documentacion_id'));
    $doc_solicitud_prestamo->setUsuarioId($usuariologuiado);
    $doc_solicitud_prestamo->setDocsolicitudprestamoestadoId(1);    
    $doc_solicitud_prestamo->setFechaCreacion(date("Y-m-d G:i:s"));
    if ($this->getRequestParameter('fecha_atencion'))
    {      
      $doc_solicitud_prestamo->setFechaAtencion(date("Y-m-d G:i:s"));
    }

    $doc_solicitud_prestamo->save();
    
    return $this->redirect($this->getRequest()->getScriptName().'/documentacion_tecnica/show?documentacion_id='.$doc_solicitud_prestamo->getDocumentacionId());
    
    //return $this->redirect($this->getRequest()->getScriptName().'/solicitud_documentacion/show?docsolicitudprestamo_id='.$doc_solicitud_prestamo->getDocsolicitudprestamoId());
  }
  
